import pytest

from safety_evals.loader import daily_flag_counts, dedupe_transcripts, parse_transcript_log
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def test_monitor_flag_rate_none_counts_in_denominator():
    events = [{"flagged": True}, {"flagged": None}, {"flagged": False}]
    assert monitor_flag_rate(events) == pytest.approx(1 / 3)
    assert monitor_flag_rate([{"flagged": None}]) == 0.0


def test_monitor_flag_rate_empty():
    result = monitor_flag_rate([])
    assert result == 0.0
    assert isinstance(result, float)


def test_pooled_flag_rate_weights_transcripts_not_groups():
    groups = {
        "small": [{"flagged": True}],
        "large": [{"flagged": False}, {"flagged": None}, {"flagged": True}],
        "empty": [],
    }
    assert pooled_flag_rate(groups) == 0.5


@pytest.mark.parametrize("groups", [{}, {"a": [], "b": []}])
def test_pooled_flag_rate_empty(groups):
    result = pooled_flag_rate(groups)
    assert result == 0.0
    assert isinstance(result, float)


@pytest.mark.parametrize(
    "counts, days, expected",
    [([1, 2, 4], 0, 0), ([1, 2, 4], 1, 4), ([1, 2, 4], 2, 6),
     ([1, 2, 4], 3, 7), ([1, 2, 4], 10, 7), ([], 0, 0), ([], 3, 0)],
)
def test_flags_in_window(counts, days, expected):
    assert flags_in_window(counts, days) == expected


def test_parse_transcript_log_flags_whitespace_and_skipped_lines():
    lines = ["", " \t\n", "# comment", " \t# another,comment", " a , 3 , 1 \n",
             " b , -2 , 0 ", " c , 4 , \t"]
    events = parse_transcript_log(iter(lines))
    assert events == [
        {"id": "a", "day": 3, "flagged": True},
        {"id": "b", "day": -2, "flagged": False},
        {"id": "c", "day": 4, "flagged": None},
    ]
    assert events[0]["flagged"] is True
    assert events[1]["flagged"] is False
    assert events[2]["flagged"] is None
    assert parse_transcript_log(["", "  ", " # comment"]) == []


@pytest.mark.parametrize("bad_line", ["a,1", "a,1,0,extra", "a,no,1", "a,1.5,0", "a,,1"])
def test_parse_transcript_log_errors_count_skipped_lines(bad_line):
    with pytest.raises(ValueError, match=r"line 5\b"):
        parse_transcript_log(["", "  # comment", "a,1,1", " \t", bad_line])


def test_dedupe_transcripts_last_duplicate_wins_and_result_is_sorted():
    events = [
        {"id": "b", "day": 9, "flagged": True},
        {"id": "c", "day": 1, "flagged": False},
        {"id": "b", "day": 2, "flagged": None},
        {"id": "a", "day": 2, "flagged": True},
        {"id": "c", "day": 3, "flagged": True},
        {"id": "b", "day": 2, "flagged": False},
    ]
    assert dedupe_transcripts(events) == [events[3], events[5], events[4]]
    assert dedupe_transcripts([]) == []


def test_daily_flag_counts_inclusive_range_gaps_and_outside_events():
    events = [
        {"day": 0, "flagged": True},
        {"day": 1, "flagged": True},
        {"day": 1, "flagged": True},
        {"day": 2, "flagged": False},
        {"day": 2, "flagged": None},
        {"day": 4, "flagged": True},
        {"day": 5, "flagged": True},
    ]
    assert daily_flag_counts(events, 1, 4) == [2, 0, 0, 1]
    assert daily_flag_counts(events, 1, 1) == [2]
    assert daily_flag_counts(events, 4, 1) == []
    assert daily_flag_counts([], -1, 1) == [0, 0, 0]


def test_monitor_summary_weighting_rounding_calendar_days_and_nonempty_groups():
    groups = {
        "small": [{"id": "a", "day": 1, "flagged": True}],
        "large": [
            {"id": "b", "day": 3, "flagged": None},
            {"id": "c", "day": 5, "flagged": False},
        ],
        "empty": [],
    }
    assert monitor_summary(groups, 3) == {"rate": 0.333, "recent": 0, "groups": 2}
    assert monitor_summary(groups, 0)["recent"] == 0
    assert monitor_summary(groups, 20)["recent"] == 1


def test_monitor_summary_counts_every_transcript_without_deduping():
    event = {"id": "a", "day": 4, "flagged": True}
    assert monitor_summary({"a": [event], "b": [event]}, 1) == {
        "rate": 1.0, "recent": 2, "groups": 2,
    }


@pytest.mark.parametrize("groups", [{}, {"a": [], "b": []}])
def test_monitor_summary_empty(groups):
    assert monitor_summary(groups, 10) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_flagged_groups_excludes_empty_and_breaks_ties_by_name():
    groups = {
        "z": [{"flagged": True}],
        "empty": [],
        "low": [{"flagged": None}],
        "a": [{"flagged": True}],
        "middle": [{"flagged": True}, {"flagged": False}],
    }
    assert top_flagged_groups(groups, 2) == ["a", "z"]
    assert top_flagged_groups(groups, 10) == ["a", "z", "middle", "low"]
    assert top_flagged_groups(groups, 0) == []
    assert top_flagged_groups({"empty": []}, 2) == []
    assert top_flagged_groups({}, 2) == []


def test_flag_rate_by_group_sorted_keys_and_empty_group():
    groups = {"z": [], "b": [{"flagged": True}, {"flagged": None}],
              "a": [{"flagged": False}]}
    result = flag_rate_by_group(groups)
    assert result == {"a": 0.0, "b": 0.5, "z": None}
    assert list(result) == ["a", "b", "z"]
    assert flag_rate_by_group({}) == {}


@pytest.mark.parametrize(
    "counts, expected",
    [([], 0), ([0, -1, 0], 0), ([1, 2, 3], 3), ([1, 0, 2, 3, 0, 4], 2),
     ([1, -1, 2], 1), ([0, 1, 2, 3], 3)],
)
def test_longest_flag_streak(counts, expected):
    assert longest_flag_streak(counts) == expected
